template<typename T>
void forwarder(T&& t) { otherFunction(std::forward<T>(t)); }
int main() {
  int i = 5; 
  forwarder(i);       // Forwards lvalue, modifies original i
  forwarder(10);      // Forwards rvalue, temporary not modified
  return 0;
}
```

